import{_ as t,o as h,c as i,b6 as g,bT as r,bU as a,bV as o,bW as c,bX as e,bY as l,bZ as s,b_ as u,b$ as d,c0 as p,c1 as m,c2 as b,c3 as k,c4 as v,c5 as y,c6 as _,c7 as q,c8 as f,c9 as A,ca as x,cb as I,cc as P,cd as C,ce as T,cf as w,cg as V,ch as N,ci as S,cj as W,ck as L,cl as D,cm as G,cn as M,co as H,cp as R}from"./chunks/framework.BUXTSoD9.js";const F=JSON.parse('{"title":"So sánh 7 công cụ lập trình AI","description":"","frontmatter":{},"headers":[],"relativePath":"vi-vn/stage-1/appendix-articles/example0-1/vibe-coding-tools-snake-game-tutorial.md","filePath":"vi-vn/stage-1/appendix-articles/example0-1/vibe-coding-tools-snake-game-tutorial.md"}'),U={name:"vi-vn/stage-1/appendix-articles/example0-1/vibe-coding-tools-snake-game-tutorial.md"};function K(B,n,X,E,Q,Z){return h(),i("div",null,[...n[0]||(n[0]=[g('<h1 id="so-sanh-7-cong-cu-lap-trinh-ai" tabindex="-1">So sánh 7 công cụ lập trình AI <a class="header-anchor" href="#so-sanh-7-cong-cu-lap-trinh-ai" aria-label="Permalink to “So sánh 7 công cụ lập trình AI”">​</a></h1><h2 id="huong-dan-chuong-nay" tabindex="-1">Hướng dẫn chương này <a class="header-anchor" href="#huong-dan-chuong-nay" aria-label="Permalink to “Hướng dẫn chương này”">​</a></h2><p>Đối mặt với vô số công cụ lập trình AI, công cụ nào mới phù hợp với bạn nhất? Chương này thông qua một nhiệm vụ thực chiến thống nhất -- phát triển trò chơi &quot;Rắn ăn mồi + AI làm thơ&quot;, đánh giá chéo 7 nền tảng Web Vibe Coding phổ biến như Lovable, Replit, Z.ai. Chúng ta sẽ so sánh đa chiều từ mức độ thân thiện với người mới, khả năng kiểm soát code, tính tiện lợi triển khai, giúp bạn nhanh chóng chọn ra công cụ hỗ trợ phát triển mạnh nhất.</p><hr><h1 id="_1-dung-vibe-coding-xay-tro-snake-huong-dan-thuc-chien-hoan-chinh" tabindex="-1">1. Dùng Vibe Coding xây trò Snake: Hướng dẫn thực chiến hoàn chỉnh <a class="header-anchor" href="#_1-dung-vibe-coding-xay-tro-snake-huong-dan-thuc-chien-hoan-chinh" aria-label="Permalink to “1. Dùng Vibe Coding xây trò Snake: Hướng dẫn thực chiến hoàn chỉnh”">​</a></h1><p>Bài viết giới thiệu một phương pháp phát triển phần mềm mới nổi -- &quot;Vibe Coding&quot;, sử dụng trí tuệ nhân tạo để tăng tốc quá trình xây dựng ứng dụng.</p><p>Tiếp theo chúng ta sẽ lần lượt giới thiệu khái niệm cốt lõi của Vibe Coding, giải thích AI Agent là gì, và cung cấp phương pháp viết prompt thực dụng. Cuối cùng, thông qua thực chiến hoàn chỉnh xây dựng trò &quot;Snake (Rắn săn mồi)&quot; từ đầu, và đánh giá so sánh chi tiết nhiều nền tảng Vibe Coding phổ biến, giúp bạn chọn bộ công cụ phù hợp nhất với mình.</p><h2 id="ban-se-hoc-đuoc" tabindex="-1">Bạn sẽ học được: <a class="header-anchor" href="#ban-se-hoc-đuoc" aria-label="Permalink to “Bạn sẽ học được:”">​</a></h2><ul><li><strong>Vibe Coding là gì:</strong> Hiểu định nghĩa, workflow và lợi thế chính của nó.</li><li><strong>Vai trò của AI Agent:</strong> Hiểu cách làm việc của AI Agent, và sự khác biệt với chương trình truyền thống.</li><li><strong>Cách viết prompt tốt:</strong> Nắm vững cách viết prompt rõ ràng, cụ thể, để nhận kết quả tốt hơn.</li><li><strong>Công cụ Vibe Coding:</strong> Làm quen với một loạt nền tảng lập trình và thiết kế AI phổ biến.</li><li><strong>So sánh nền tảng:</strong> Đánh giá và so sánh ưu nhược điểm của 7 nền tảng AI Agent khác nhau từ góc nhìn người mới bắt đầu.</li><li><strong>Công cụ UI / UX:</strong> Học cách tích hợp các công cụ UI/UX như Figma, Mastergo vào workflow tổng thể.</li></ul><h2 id="_1-gioi-thieu" tabindex="-1">1. Giới thiệu <a class="header-anchor" href="#_1-gioi-thieu" aria-label="Permalink to “1. Giới thiệu”">​</a></h2><p>Trong các bài học trước, chúng ta luôn sử dụng mô hình phát triển fullstack của z.ai để hoàn thành nhiệm vụ lập trình.</p><p>Tuy nhiên, chúng ta có bao giờ nghĩ: cốt lõi của nó thực ra là &quot;AI Agent&quot; (khác với AI chat thông thường, và thông minh hơn nhiều)? Vì nó không chỉ trò chuyện với bạn, mà còn có thể suy nghĩ (khi bạn giao nhiệm vụ, nó sẽ trước lập kế hoạch), còn có thể chủ động hành động (ví dụ gọi tìm kiếm web, thực thi lệnh máy tính, mở trang web, v.v.). Chúng ta sẽ giới thiệu chi tiết hơn ở phần sau.</p><h2 id="_1-vibe-coding-la-gi" tabindex="-1">1. Vibe Coding là gì? <a class="header-anchor" href="#_1-vibe-coding-la-gi" aria-label="Permalink to “1. Vibe Coding là gì?”">​</a></h2><p>Vibe Coding là một phương pháp phát triển phần mềm kiểu mới sử dụng AI để tăng tốc quá trình phát triển ứng dụng. Nó không phải sản phẩm thay thế lập trình truyền thống, mà là một chế độ lập trình &quot;hội thoại&quot; hơn. Khái niệm này được nhà nghiên cứu AI Andrej Karpathy đề xuất: trong workflow này, nhà phát triển không còn tự viết code từng dòng, mà chủ yếu thông qua hướng dẫn AI Agent để tạo, tối ưu và debug ứng dụng.</p><p>Tư tưởng cốt lõi của Vibe Coding, là chuyển từ <strong>&quot;lấy code làm trung tâm (code-first)&quot;</strong> sang <strong>&quot;lấy ý định làm trung tâm (intent-first)&quot;</strong>. Bạn không cần suy nghĩ từ dòng code đầu tiên, mà dùng ngôn ngữ tự nhiên mô tả kết quả bạn muốn.</p><p>Workflow điển hình của Vibe Coding là một vòng lặp liên tục:</p><ul><li><strong>Mô tả mục tiêu:</strong> Trước dùng một câu hoặc một đoạn mô tả chức năng bạn muốn triển khai, ví dụ: &quot;Làm một trò Snake đơn giản có backend Python, có thể sinh thơ.&quot;</li><li><strong>AI tạo code:</strong> AI Agent phân tích nhu cầu của bạn, tạo code phiên bản đầu, bao gồm cấu trúc cơ bản, trang frontend và logic backend.</li><li><strong>Chạy và quan sát:</strong> Chạy code đã tạo, kiểm tra có hoạt động đúng như mong đợi không, đồng thời phát hiện bug hoặc điểm chưa tốt.</li><li><strong>Phản hồi và lặp lại:</strong> Nếu có lỗi hoặc hiệu quả không lý tưởng, tiếp tục ra lệnh trong hội thoại, ví dụ: &quot;Rắn di chuyển quá chậm, tăng tốc độ lên&quot;, hoặc &quot;Hiện file <code>.env</code> không đọc đúng API Key, xin sửa code backend.&quot;</li><li><strong>Lặp lại các bước trên:</strong> Liên tục lặp trong vòng &quot;mô tả → tạo → chạy → phản hồi&quot; cho đến khi ứng dụng đạt trạng thái hài lòng.</li></ul><h3 id="loi-the-chinh-cua-vibe-coding" tabindex="-1">Lợi thế chính của Vibe Coding: <a class="header-anchor" href="#loi-the-chinh-cua-vibe-coding" aria-label="Permalink to “Lợi thế chính của Vibe Coding:”">​</a></h3><ul><li><strong>Giảm rào cản:</strong> Để nhà thiết kế, doanh nhân, sinh viên thiếu kinh nghiệm lập trình cũng có thể tham gia phát triển ứng dụng thông qua ngôn ngữ tự nhiên.</li><li><strong>Prototype nhanh chóng:</strong> Thời gian từ ý tưởng đến sản phẩm khả thi tối thiểu (MVP) giảm đáng kể.</li><li><strong>Nâng cao hiệu quả:</strong> Tự động xử lý lượng lớn công việc lập trình lặp đi lặp lại, cơ học (như code template), để nhà phát triển tập trung sức vào thiết kế kiến trúc và trừu tượng hóa vấn đề.</li><li><strong>Thuận lợi thử nghiệm:</strong> Khuyến khích cách sản xuất nhanh rồi hoàn thiện dần, tiện thử ý tưởng và chức năng mới hơn.</li></ul><h2 id="_2-nen-tang-vibe-coding-truc-tuyen-web-based-la-gi" tabindex="-1">2. Nền tảng Vibe Coding trực tuyến (Web-based) là gì? <a class="header-anchor" href="#_2-nen-tang-vibe-coding-truc-tuyen-web-based-la-gi" aria-label="Permalink to “2. Nền tảng Vibe Coding trực tuyến (Web-based) là gì?”">​</a></h2><p>Trong lần thử nghiệm thực tế này, bạn sẽ phát hiện công cụ chúng ta đánh giá được chia thành hai loại: <strong>Web-based (nền tảng trực tuyến)</strong> và <strong>IDE (môi trường phát triển cục bộ)</strong>.</p><p>Dù cốt lõi đều là dùng AI giúp bạn viết code, nhưng trải nghiệm sử dụng và kịch bản áp dụng có sự khác biệt rất lớn:</p><h3 id="nen-tang-vibe-coding-truc-tuyen-web-based" tabindex="-1">Nền tảng Vibe Coding trực tuyến (Web-based) <a class="header-anchor" href="#nen-tang-vibe-coding-truc-tuyen-web-based" aria-label="Permalink to “Nền tảng Vibe Coding trực tuyến (Web-based)”">​</a></h3><p><strong>Công cụ đại diện:</strong> Lovable, Replit, Z.ai, v0</p><p>Giống như căn hộ dịch vụ &quot;xách vali vào ở&quot;.</p><ul><li><strong>Không cần cấu hình môi trường:</strong> Bạn không cần quan tâm Python là gì, phiên bản Node.js ra sao, cũng không cần lo cài đặt dependency. Mở trình duyệt, nhập URL, có thể bắt đầu viết code ngay.</li><li><strong>Xem trước và triển khai một lần:</strong> Sau khi code được tạo, nền tảng thường tự động hiển thị kết quả chạy ở cửa sổ bên phải. Làm xong, click một nút đã có thể tạo link chia sẻ cho bạn bè.</li><li><strong>Kịch bản phù hợp:</strong><ul><li><strong>Xác minh ý tưởng nhanh chóng (MVP):</strong> Trong đầu có ý tưởng, muốn mất nửa tiếng xem có thể làm ra hay không.</li><li><strong>Người mới bắt đầu:</strong> Hoàn toàn không muốn bị lỗi môi trường phức tạp làm nản, chỉ muốn trải nghiệm niềm vui lập trình AI.</li><li><strong>Ứng dụng nhẹ:</strong> Làm một trang công cụ đơn giản, game nhỏ hoặc trang cá nhân.</li></ul></li></ul><h3 id="ai-ide-moi-truong-phat-trien-cuc-bo" tabindex="-1">AI IDE (Môi trường phát triển cục bộ) <a class="header-anchor" href="#ai-ide-moi-truong-phat-trien-cuc-bo" aria-label="Permalink to “AI IDE (Môi trường phát triển cục bộ)”">​</a></h3><p><strong>Công cụ đại diện:</strong> Cursor, Trae, VS Code + AI plugin</p><p>Giống như nhà ở &quot;trang trí đầy đủ&quot; tự sở hữu.</p><ul><li><strong>Khả năng cục bộ mạnh mẽ:</strong> Nó chạy trên máy của bạn, có thể trực tiếp truy cập tất cả file cục bộ, tận dụng sức mạnh tính toán máy của bạn.</li><li><strong>Kết nối liền mạch workflow chuyên nghiệp:</strong> Phù hợp dự án lớn, có thể tự do cài đặt plugin, kết nối database cục bộ, debug phức tạp.</li><li><strong>Kịch bản phù hợp:</strong><ul><li><strong>Phát triển dự án chuyên nghiệp:</strong> Cần bảo trì dài hạn, dự án thương mại có cấu trúc phức tạp.</li><li><strong>Tùy chỉnh sâu:</strong> Cần kiểm soát chi tiết code đến mức cực đoan, hoặc cần kết hợp sâu với workflow cục bộ hiện có (như Git, Docker).</li><li><strong>Quyền riêng tư dữ liệu:</strong> Code hoàn toàn ở cục bộ, phù hợp hơn với quy định an toàn của một số doanh nghiệp.</li></ul></li></ul><p><strong>Tóm lại:</strong> Nếu bạn mới tiếp xúc lập trình AI, hoặc chỉ muốn nhanh làm một thứ nhỏ để vui, <strong>nền tảng trực tuyến</strong> là điểm khởi đầu tuyệt vời. Nếu bạn là nhà phát triển chuyên nghiệp, hoặc dự án ngày càng phức tạp, <strong>IDE cục bộ</strong> sẽ cung cấp giới hạn trên cao hơn.</p><hr><h2 id="_3-ai-agent-la-gi" tabindex="-1">3. AI Agent là gì? <a class="header-anchor" href="#_3-ai-agent-la-gi" aria-label="Permalink to “3. AI Agent là gì?”">​</a></h2><h3 id="ai-agent-la-gi" tabindex="-1">AI Agent là gì? <a class="header-anchor" href="#ai-agent-la-gi" aria-label="Permalink to “AI Agent là gì?”">​</a></h3><p>AI Agent là một hệ thống phần mềm, có khả năng nhận thức môi trường, ra quyết định, và tự chủ hành động để đạt mục tiêu cụ thể. So với phần mềm truyền thống tuân theo chỉ thị cố định, quy trình đơn lẻ, AI Agent linh hoạt và tự thích nghi hơn.</p><p>Dưới đây là một số đặc điểm chính phân biệt AI Agent với chương trình truyền thống:</p><ul><li><strong>Tự chủ (Autonomy):</strong> AI Agent có tính độc lập cao. Chương trình truyền thống thường cần người kích hoạt từng bước, còn Agent có thể tự quyết định bước tiếp theo làm gì dựa trên mục tiêu.</li><li><strong>Nhận thức và trí nhớ (Perception &amp; Memory):</strong> Agent thu thập dữ liệu từ môi trường (ví dụ phản hồi API, dữ liệu cảm biến, đầu vào người dùng, v.v.), và giữ lại ngữ cảnh thông qua &quot;trí nhớ&quot;, từ đó tái sử dụng kinh nghiệm và cải thiện hiệu quả liên tục trong hành động sau.</li><li><strong>Lý tính và hướng mục tiêu (Rationality &amp; Goal-Orientation):</strong> Agent sẽ phân tích và lập kế hoạch xoay quanh mục tiêu đã cho, chọn chuỗi hành động phù hợp nhất để theo đuổi &quot;chỉ số hiệu suất&quot; cao hơn.</li><li><strong>Sử dụng công cụ (Tool Use):</strong> Đặc điểm lớn của AI Agent hiện đại là có thể gọi công cụ bên ngoài, không còn giới hạn ở &quot;tạo văn bản&quot;. Ví dụ, nó có thể duyệt web, chạy code, truy vấn database, gửi email, là một bộ não &quot;điều độ công cụ&quot;.</li></ul><p>Có thể hiểu theo phép loại suy:</p><ul><li>Một <strong>chương trình truyền thống</strong> giống như máy tính. Bạn cho nó nhập số và toán tử, nó chỉ thực hiện tính toán khi bạn bấm nút.</li><li>Một <strong>trợ lý AI</strong> giống như trợ lý con người. Bạn bảo &quot;giúp tôi tìm nhà hàng gần đây&quot;, nó sẽ cho bạn kết quả tìm kiếm và liệt kê lựa chọn, nhưng cuối cùng vẫn là bạn ra quyết định.</li><li>Một <strong>AI Agent</strong> giống hơn như một đội nghiên cứu tự động. Bạn chỉ cần đưa ra mục tiêu cấp cao (ví dụ &quot;giúp tôi lên kế hoạch một chuyến đi Nhật&quot;), nó sẽ phân tách nhiệm vụ, tra cứu mạng, đặt vé máy bay khách sạn (qua API), sắp xếp lịch trình, cuối cùng giao kết quả cho bạn, gần như không cần bạn can thiệp chi tiết.</li></ul><hr><h1 id="_2-ve-viet-prompt" tabindex="-1">2. Về viết prompt <a class="header-anchor" href="#_2-ve-viet-prompt" aria-label="Permalink to “2. Về viết prompt”">​</a></h1><h2 id="_1-prompt-viet-xong-ngay-tot-hay-chia-thanh-nhieu-buoc-tot-hon" tabindex="-1">1. Prompt viết xong ngay tốt, hay chia thành nhiều bước tốt hơn? <a class="header-anchor" href="#_1-prompt-viet-xong-ngay-tot-hay-chia-thanh-nhieu-buoc-tot-hon" aria-label="Permalink to “1. Prompt viết xong ngay tốt, hay chia thành nhiều bước tốt hơn?”">​</a></h2><p>Rất nhiều người sẽ không nhịn được muốn trực tiếp trong một prompt, nói rõ &quot;làm một ứng dụng fullstack hoàn chỉnh&quot; cùng lúc. Thực tế, công cụ hiện tại đã đủ mạnh, xác thực có cơ hội cho kết quả trông khá ổn ngay lần đầu. Nhưng xét về trải nghiệm tổng thể và tỷ lệ thành công, chia công việc thành các bước nhỏ, lặp theo giai đoạn, kết quả thường tốt hơn, cũng ít dễ rơi vào ngõ cụt &quot;sửa không được&quot; hơn.</p><blockquote><p><strong>Mẹo nhỏ:</strong> Thay vì kỳ vọng &quot;làm đúng ngay một lần&quot;, tốt hơn chia mục tiêu lớn thành các todo nhỏ có thể thực hiện.<br> Ví dụ, đừng trực tiếp nói &quot;build me a Snake game&quot;, mà chia thành:<br> &quot;1. Trước làm frontend của trò Snake&quot;,<br> &quot;2. Rồi triển khai một backend ghi điểm&quot;,<br> &quot;3. Cuối cùng nối frontend và backend lại&quot;.<br> Như vậy có thể khiến AI hiểu chính xác nhu cầu của bạn hơn và cho output đáng tin cậy hơn.</p></blockquote><h2 id="_2-cang-ro-rang-cang-tot" tabindex="-1">2. Càng rõ ràng, càng tốt <a class="header-anchor" href="#_2-cang-ro-rang-cang-tot" aria-label="Permalink to “2. Càng rõ ràng, càng tốt”">​</a></h2><ul><li>Trong Vibe Coding, prompt bạn viết quan trọng không kém code bạn viết. Prompt càng rõ ràng, càng cụ thể, kết quả càng gần với ý bạn nghĩ.</li><li>Nói rõ mục tiêu và ràng buộc ngay từ đầu, có thể giảm số lần sửa đổi sau, không chỉ tiết kiệm thời gian, cũng tiết kiệm quota sử dụng và chi phí.</li></ul><hr><h1 id="_3-tong-quan-cong-cu-vibe-coding-uiux" tabindex="-1">3. Tổng quan công cụ (Vibe Coding / UIUX) <a class="header-anchor" href="#_3-tong-quan-cong-cu-vibe-coding-uiux" aria-label="Permalink to “3. Tổng quan công cụ (Vibe Coding / UIUX)”">​</a></h1><h2 id="_1-nen-tang-ai-agent" tabindex="-1">1. Nền tảng AI Agent <a class="header-anchor" href="#_1-nen-tang-ai-agent" aria-label="Permalink to “1. Nền tảng AI Agent”">​</a></h2><table tabindex="0"><thead><tr><th><strong>Name</strong></th><th><strong>Platform</strong></th></tr></thead><tbody><tr><td><strong><a href="https://lovable.dev/" target="_blank" rel="noreferrer">Lovable</a></strong></td><td>Web-based</td></tr><tr><td><strong><a href="https://cursor.com/cn/agents" target="_blank" rel="noreferrer">Cursor</a></strong></td><td>PC</td></tr><tr><td><strong><a href="https://chat.z.ai/" target="_blank" rel="noreferrer">Z.ai</a></strong></td><td>Web-based</td></tr><tr><td><strong><a href="https://replit.com/~" target="_blank" rel="noreferrer">Replit</a></strong></td><td>Web-based</td></tr><tr><td><strong><a href="https://agent.minimaxi.com/" target="_blank" rel="noreferrer">Minimax</a></strong></td><td>Web-based</td></tr><tr><td><strong><a href="https://www.trae.ai/" target="_blank" rel="noreferrer">Trae</a></strong></td><td>PC</td></tr><tr><td><strong><a href="https://v0.app/" target="_blank" rel="noreferrer">V0</a></strong></td><td>Web-based</td></tr></tbody></table><h2 id="_2-nen-tang-ai-uiux" tabindex="-1">2. Nền tảng AI UIUX <a class="header-anchor" href="#_2-nen-tang-ai-uiux" aria-label="Permalink to “2. Nền tảng AI UIUX”">​</a></h2><table tabindex="0"><thead><tr><th><strong>Name</strong></th><th><strong>Platform</strong></th></tr></thead><tbody><tr><td><strong><a href="https://mastergo.com/" target="_blank" rel="noreferrer">Mastergo</a></strong></td><td>Web-based</td></tr><tr><td><strong><a href="https://www.figma.com/" target="_blank" rel="noreferrer">FIgma</a></strong></td><td>Web-based, PC Plugin</td></tr></tbody></table><hr><h1 id="_4-huong-dan-thuc-chien-vibe-coding-ui-ket-hop" tabindex="-1">4. Hướng dẫn thực chiến (Vibe Coding + UI kết hợp) <a class="header-anchor" href="#_4-huong-dan-thuc-chien-vibe-coding-ui-ket-hop" aria-label="Permalink to “4. Hướng dẫn thực chiến (Vibe Coding + UI kết hợp)”">​</a></h1><ol><li><p>Trong cửa sổ chat của nền tảng Vibe Coding bạn chuẩn bị sử dụng, nhập mô tả chương trình bạn muốn. Ví dụ:</p><blockquote><p>Xin xây dựng một ứng dụng web Snake đơn giản với frontend và backend.</p><ol><li>Frontend</li></ol><ul><li>Trang 1: Trang game <ul><li>Dùng phím điều khiển di chuyển của rắn.</li><li>Rắn ăn không phải thức ăn, mà là từ tiếng Anh.</li><li>Thanh bên trang hiển thị từ đã thu thập và số lượng.</li><li>Sau khi game over, từ đã thu thập vẫn được giữ lại, tiếp tục trong ván mới.</li></ul></li><li>Trang 2: Trang làm thơ (Make Poem) <ul><li>Hiển thị cùng danh sách từ như trang game (dữ liệu đồng nhất).</li><li>Cung cấp nút, gửi từ hiện thu thập cho backend để tạo một bài thơ.</li><li>Sau khi sinh thơ, từ đã sử dụng bị xóa khỏi danh sách hoặc giảm số đếm.</li></ul></li></ul><ul><li>Thêm điều hướng đơn giản, chuyển đổi giữa hai trang Game và Make Poem.</li><li>Đảm bảo từ thu thập được nhìn thấy ở cả hai trang.</li></ul><ol start="2"><li>Backend</li></ol><ul><li>Cung cấp một API backend, nhận từ đã thu thập và trả về một bài thơ.</li><li>Dùng DeepSeek API để tạo thơ.</li><li>Lưu API Key trong file <code>.env</code>, và ignore file này trong <code>.gitignore</code>.</li></ul></blockquote></li><li><p>Nhập DeepSeek API Key của bạn. (Có thể lấy tại <a href="https://platform.deepseek.com/" target="_blank" rel="noreferrer">https://platform.deepseek.com/</a>)</p><ol><li>API Key của LLM dùng để gọi mô hình lớn trong dự án của bạn. Vì đây là thông tin nhạy cảm, không thể công khai, nên cần viết riêng trong file cấu hình. <strong>Tại sao phải dùng file <code>.env</code>, và không upload nó lên GitHub?</strong></li></ol><ul><li>File <code>.env</code> chuyên dùng để lưu <strong>khóa hoặc mật khẩu</strong> (ví dụ DeepSeek API Key).</li><li>Nếu file này bị upload lên GitHub, tất cả mọi người trên thế giới đều thấy được khóa của bạn và sử dụng trái phép.</li><li>Vì lý do an toàn, chúng ta cần khai báo ignore <code>.env</code> trong file <code>.gitignore</code>, để Git không theo dõi nó.</li><li>Như vậy, dự án của bạn vẫn có thể sử dụng các khóa này bình thường trên máy cục bộ, mà sẽ không bị rò rỉ trong repository.</li></ul></li><li><p>Sau khi xem kết quả tạo, nếu phát hiện lỗi hoặc cần sửa, có thể trực tiếp nhập yêu cầu sửa trong cửa sổ chat.</p></li><li><p>Nếu bạn không hài lòng với thiết kế trang, cũng có thể chọn thiết kế lại giao diện trong Figma hoặc Mastergo, rồi phản hồi ý thiết kế cho Agent.</p></li></ol><ul><li><strong>Ví dụ</strong></li></ul><blockquote><p>Xin thiết kế một <strong>ứng dụng web hai trang</strong> tên <em>Word-Snake</em>.</p><ul><li><strong>Trang Game:</strong></li><li>Rắn điều khiển di chuyển bằng phím.</li><li>Rắn ăn là từ tiếng Anh, không phải thức ăn thông thường.</li><li>Panel bên phải hiển thị từ đã thu thập và số lượng.</li><li>Sau khi game over, kho từ không bị xóa, tiếp tục sử dụng ở ván mới.</li><li><strong>Trang Make Poem:</strong></li><li>Hiển thị cùng kho từ chia sẻ.</li><li>Người dùng chọn một phần từ và click nút <strong>Generate Poem</strong>.</li><li>Gửi các từ này cho backend, dùng DeepSeek API tạo thơ.</li><li>Sau khi sinh thơ, xóa hoặc giảm số lượng từ đã sử dụng trong kho.</li><li><strong>Điều hướng:</strong> Chuyển đổi giữa hai trang qua Tab đơn giản hoặc menu trên cùng.</li><li><strong>Trạng thái chia sẻ:</strong> Đảm bảo từ thu thập luôn đồng bộ và hiển thị ở cả hai trang.</li></ul></blockquote><ul><li><strong>Ví dụ kết quả</strong></li></ul><p><img src="'+r+'" alt=""><img src="'+a+'" alt=""></p><hr><h1 id="_5-so-sanh-nen-tang-ai-agent-cach-chon-to-hop-tot-nhat-cho-du-an-đon-gian" tabindex="-1">5. So sánh nền tảng AI Agent (Cách chọn tổ hợp tốt nhất cho dự án đơn giản) <a class="header-anchor" href="#_5-so-sanh-nen-tang-ai-agent-cach-chon-to-hop-tot-nhat-cho-du-an-đon-gian" aria-label="Permalink to “5. So sánh nền tảng AI Agent (Cách chọn tổ hợp tốt nhất cho dự án đơn giản)”">​</a></h1><p>Các nền tảng Vibe Coding khác nhau có đặc điểm và workflow khác nhau. Chúng ta sử dụng cùng một bộ yêu cầu &quot;trò Snake với DeepSeek API&quot; để thử nghiệm thực tế trên nhiều nền tảng, đánh giá ưu nhược điểm từ góc nhìn người mới bắt đầu. Dưới đây là tóm tắt.</p><h2 id="_1-tieu-chuan-so-sanh" tabindex="-1">1. Tiêu chuẩn so sánh <a class="header-anchor" href="#_1-tieu-chuan-so-sanh" aria-label="Permalink to “1. Tiêu chuẩn so sánh”">​</a></h2><ol><li><p><strong>Mục tiêu (Goal)</strong> Xây dựng một ứng dụng web Snake kết nối DeepSeek API.</p></li><li><p><strong>Chi tiết game (Game Details)</strong></p><ol><li>Game tạo thơ thông qua DeepSeek LLM API.</li><li>Rắn ăn từ tiếng Anh, từ thu thập được giữ lại sau game over, tiếp tục sử dụng ở ván mới. Cùng một từ có thể thu thập nhiều lần, tính riêng.</li><li>Khi tạo một bài thơ, từ đã sử dụng bị xóa khỏi kho.</li></ol></li><li><p><strong>Chức năng bắt buộc (Must-Haves)</strong></p><ol><li>Một trang frontend có thể chạy, bao gồm trò Snake (điều khiển phím, render Canvas).</li><li>Cơ chế thu thập từ (từ xuất hiện trên bàn cờ, rắn ăn từ, danh sách sidebar cập nhật).</li><li>Lưu trữ kho từ liên tục giữa nhiều ván game.</li><li>Backend sử dụng DeepSeek API (nếu không có API Key, có thể trước trả về thơ mô phỏng).</li><li>Nút &quot;sinh thơ&quot;: Sau khi click gọi backend, hiển thị thơ, và cập nhật kho từ theo sử dụng.</li><li>Hỗ trợ API Key qua <code>.env</code>, và tránh rò rỉ khóa thông qua <code>.gitignore</code>.</li></ol></li><li><p><strong>Điểm cộng (Nice-to-Haves)</strong></p><ol><li>Người dùng có thể chọn từ nào để sinh thơ.</li><li>Trải nghiệm người dùng thân thiện (ví dụ sidebar hiển thị rõ ràng danh sách từ, layout khu vực hiển thị thơ hợp lý).</li><li>Thêm comment trong code cho người mới bắt đầu, giải thích logic chính.</li></ol></li></ol><h2 id="_2-so-sanh-output-code" tabindex="-1">2. So sánh output code <a class="header-anchor" href="#_2-so-sanh-output-code" aria-label="Permalink to “2. So sánh output code”">​</a></h2><h3 id="_1-lovable-web-based" tabindex="-1">1. Lovable (Web-based) <a class="header-anchor" href="#_1-lovable-web-based" aria-label="Permalink to “1. Lovable (Web-based)”">​</a></h3><ul><li><strong>Loại nền tảng:</strong> Web</li><li><strong>Đặc điểm chính và workflow:</strong> Lovable làm tốt trong tích hợp và phối hợp, nó tự động hoàn thành các khởi tạo như kết nối database Supabase, khiến quá trình xây dựng dự án rất thuận lợi. Bạn chỉ cần mô tả nhu cầu dự án, Agent sẽ giúp bạn kết nối các loại dịch vụ, xây dựng cấu trúc cơ bản.</li><li><strong>Người dùng phù hợp:</strong> Đối với người mới lần đầu thử Vibe Coding, Lovable là lựa chọn rất thân thiện. Nó đơn giản hóa độ phức tạp của liên kết đa dịch vụ, để bạn tập trung sự chú ý vào prompt và lặp lại, thay vì cấu hình môi trường. Nhờ tự động hóa cao, bạn có thể nhanh chóng nhận được prototype chạy được.</li><li><strong>Quá trình prompt:</strong><img src="'+o+'" alt=""></li><li><strong>Hiệu quả trò Snake:</strong></li></ul><p><img src="'+c+'" alt=""><img src="'+e+'" alt=""></p><ul><li><strong>Giá:</strong> Tương đối cao, nhưng nếu bạn có email trường, có thể xác minh sinh viên để dùng với giá nửa. <img src="'+l+'" alt=""></li></ul><h3 id="_2-cursor-ide" tabindex="-1">2. Cursor (IDE) <a class="header-anchor" href="#_2-cursor-ide" aria-label="Permalink to “2. Cursor (IDE)”">​</a></h3><ul><li><strong>Loại nền tảng:</strong> Ứng dụng desktop (PC)</li><li><strong>Đặc điểm chính và workflow:</strong> Cursor là một IDE chuyên biệt tích hợp khả năng AI, hỗ trợ Windows, macOS và Linux. Nó nhúng trực tiếp tạo code, viết lại thông minh, truy vấn codebase vào môi trường phát triển. So với công cụ Web, nó gần với trải nghiệm phát triển cục bộ truyền thống hơn. Vì là môi trường cục bộ, cấu hình máy khác nhau sẽ thỉnh thoảng gặp vấn đề liên quan đến môi trường. Điểm tốt là dự án nằm ngay trên máy, không cần tải thêm hay cấu hình môi trường chạy, Cursor sẽ giúp bạn xử lý nhiều bước phức tạp.</li><li><strong>Người dùng phù hợp:</strong> Đối với người dùng đã có nền tảng lập trình nhất định, Cursor là một môi trường rất mạnh mẽ và quen thuộc. Nhưng đối với người mới hoàn toàn không có nền tảng, cần tự hiểu cấu trúc dự án, quản lý dependency và tổ chức file, đường cong học sẽ dốc hơn. Phù hợp hơn cho nhà phát triển muốn thêm trợ lý AI vào quy trình lập trình truyền thống.</li><li><strong>Quá trình prompt:</strong><img src="'+s+'" alt=""></li><li><strong>Hiệu quả trò Snake:</strong></li></ul><p><img src="'+u+'" alt=""><img src="'+d+'" alt=""></p><ul><li><strong>Giá:</strong><img src="'+p+'" alt=""></li></ul><h3 id="_3-z-ai-web-based" tabindex="-1">3. Z.ai (Web-based) <a class="header-anchor" href="#_3-z-ai-web-based" aria-label="Permalink to “3. Z.ai (Web-based)”">​</a></h3><ul><li><strong>Loại nền tảng:</strong> Web</li><li><strong>Đặc điểm chính và workflow:</strong> Cách sử dụng Z.ai khá trực tiếp, nhưng một thách thức rõ ràng là: bạn cần <strong>thủ công copy paste code đã tạo</strong>. Bản thân nền tảng thiếu cửa sổ xem trước thời gian thực, nên rất khó thấy ngay hiệu quả chạy code.</li><li><strong>Người dùng phù hợp:</strong> Nền tảng này yêu cầu cách sử dụng &quot;động tay&quot; hơn. Thiếu tự động hóa nghĩa là bạn phải trực tiếp đối mặt với code, điều này đối với người muốn hiểu sâu nội dung AI output lại là một dạng rèn luyện. Nhưng copy paste thường xuyên sẽ mang lại vấn đề hiệu quả và nguy cơ sai sót. Phù hợp hơn cho người muốn xem &quot;raw AI output code&quot;, chứ không phải người theo đuổi trải nghiệm một lần click.</li><li><strong>Quá trình prompt:</strong><img src="'+m+'" alt=""></li><li><strong>Hiệu quả trò Snake:</strong></li></ul><p><img src="'+b+'" alt=""><img src="'+k+'" alt=""></p><ul><li><strong>Giá:</strong><img src="'+v+'" alt=""></li></ul><h3 id="_4-replit-web-based" tabindex="-1">4. Replit (Web-based) <a class="header-anchor" href="#_4-replit-web-based" aria-label="Permalink to “4. Replit (Web-based)”">​</a></h3><ul><li><p><strong>Loại nền tảng:</strong> Web</p></li><li><p><strong>Đặc điểm chính và workflow:</strong> Replit là môi trường phát triển và triển khai trực tuyến tất cả trong một, trong trình duyệt đã có thể viết code, chạy chương trình, tạo địa chỉ truy cập online. Trước khi bắt đầu code, nó sẽ đưa ra kế hoạch hành động rõ ràng; đồng thời cung cấp editor trực quan, bạn có thể sửa UI trực tiếp trong cửa sổ xem trước, source code tự động đồng bộ cập nhật. Như vậy có thể bạn luôn xác nhận output của AI có đúng kỳ vọng không, giảm đáng kể số lần sửa đổi qua lại.</p><p><img src="'+y+'" alt=""></p></li><li><p><strong>Người dùng phù hợp:</strong> Replit rất thân thiện với người mới. Nó đơn giản hóa vòng khép kín hoàn chỉnh từ code đến triển khai, không cần tự cấu hình server hay hosting thêm. Chức năng phối hợp cũng rất mạnh, phù hợp bạn học cùng làm dự án hoặc nhờ người khác hỗ trợ xem code từ xa.</p></li><li><p><strong>Quá trình prompt:</strong> Trong quá trình xây dựng, AI không phải ngay từ đầu đã hiểu hoàn toàn nhu cầu, trải qua khoảng 3 vòng lặp, output cuối cùng mới đạt hiệu quả lý tưởng. <img src="'+_+'" alt=""></p></li><li><p><strong>Hiệu quả trò Snake:</strong></p></li></ul><p><img src="'+q+'" alt=""><img src="'+f+'" alt=""></p><ul><li><strong>Giá:</strong><img src="'+A+'" alt=""></li></ul><h3 id="_5-minimax-web-based" tabindex="-1">5. Minimax (Web-based) <a class="header-anchor" href="#_5-minimax-web-based" aria-label="Permalink to “5. Minimax (Web-based)”">​</a></h3><ul><li><strong>Loại nền tảng:</strong> Web</li><li><strong>Đặc điểm chính và workflow:</strong> Minimax thường mất nhiều thời gian hơn khi thực thi nhiệm vụ. Quy trình thường bao gồm: AI tự động phát hiện và sửa lỗi, vì vậy toàn bộ quá trình có thể chậm hơn, thậm chí hơi rắc rối. Lấy dự án này làm ví dụ, Agent thường trước tạo một kế hoạch chi tiết, rồi từng bước xây dựng backend, database và logic frontend.</li><li><strong>Người dùng phù hợp:</strong> Vì nó sẽ tự động chạy test và sửa lỗi, thời gian và tiêu thụ Token đều khá lớn, nhưng bạn có thể rõ ràng thấy AI định vị và giải quyết vấn đề thế nào, từ góc độ học tập rất có giá trị.</li><li><strong>Quá trình prompt:</strong></li></ul><p><img src="'+x+'" alt=""><img src="'+I+'" alt=""><img src="'+P+'" alt=""><img src="'+C+'" alt=""></p><ul><li><strong>Hiệu quả trò Snake:</strong></li></ul><p><img src="'+T+'" alt=""><img src="'+w+'" alt=""></p><ul><li><strong>Giá:</strong> Phiên bản miễn phí trong dự án phức tạp rất có thể không chạy từ đầu đến cuối suôn sẻ, nên khuyến nghị nâng cấp trả phí, để đảm bảo dự án có thể xây dựng hoàn chỉnh. <img src="'+V+'" alt=""></li></ul><h3 id="_6-trae-ide" tabindex="-1">6. Trae (IDE) <a class="header-anchor" href="#_6-trae-ide" aria-label="Permalink to “6. Trae (IDE)”">​</a></h3><ul><li><strong>Loại nền tảng:</strong> Ứng dụng desktop (PC)</li><li><strong>Đặc điểm chính và workflow:</strong> Là ứng dụng desktop, Trae so với công cụ Web thường có ưu thế hơn về hiệu năng và tốc độ phản hồi. Nhưng nó cần tải và cài đặt, đối với một số người dùng rào cản ban đầu hơi cao. Tương tự, vì là môi trường cục bộ, sự khác biệt về cấu hình máy và môi trường dependency sẽ mang lại một số không chắc chắn. Ưu điểm là Trae sẽ giúp bạn hoàn thành tạo dự án và cấu hình chạy ở cục bộ, bạn có thể trực tiếp phát triển và debug trên máy.</li><li><strong>Người dùng phù hợp:</strong> Phù hợp hơn cho người dùng kế hoạch tiến hành dự án Vibe Coding dài hạn, và muốn sử dụng tổ hợp công cụ desktop chuyên dụng. Đối với người chỉ muốn &quot;thỉnh thoảng chơi thử&quot;, có thể không phải lựa chọn nhẹ nhất.</li><li><strong>Quá trình prompt:</strong><img src="'+N+'" alt=""></li><li><strong>Hiệu quả trò Snake:</strong></li></ul><p><img src="'+S+'" alt=""><img src="'+W+'" alt=""></p><ul><li><strong>Giá:</strong> Giá tương đối hợp lý, kể cả phiên bản miễn phí cũng đủ để hoàn thành dự án nhỏ chất lượng khá. <img src="'+L+'" alt=""></li></ul><h3 id="_7-v0-web-based" tabindex="-1">7. V0 (Web-based) <a class="header-anchor" href="#_7-v0-web-based" aria-label="Permalink to “7. V0 (Web-based)”">​</a></h3><ul><li><p><strong>Loại nền tảng:</strong> Web</p></li><li><p><strong>Đặc điểm chính và workflow:</strong> V0 là một công cụ tập trung vào tạo component UI React, do Vercel cung cấp. Nó thể hiện xuất sắc trong việc tạo giao diện chất lượng cao, có thể dùng cho môi trường production. Nhưng trong sử dụng thực tế, sẽ gặp những vấn đề như &quot;khó tìm code view&quot;, &quot;không nói rõ API Key nên cấu hình ở đâu&quot;.</p></li><li><p><strong>Người dùng phù hợp:</strong> V0 rất phù hợp cho sinh viên hoặc nhà thiết kế tập trung vào frontend và UI/UX. Nhưng nó không phải giải pháp fullstack hoàn chỉnh, bạn vẫn cần sử dụng nền tảng khác để triển khai logic backend và tích hợp API, vì vậy nếu mục tiêu của bạn là &quot;xây ứng dụng hoàn chỉnh tại chỗ&quot;, nó có thể không phải lựa chọn hàng đầu.</p></li><li><p><strong>Quá trình prompt:</strong><img src="'+D+'" alt=""></p><p><img src="'+G+'" alt=""></p></li><li><p><strong>Hiệu quả trò Snake:</strong><img src="'+M+'" alt=""><img src="'+H+'" alt=""></p></li><li><p><strong>Giá:</strong> Người dùng miễn phí khoảng có thể xây dựng 4-5 dự án đơn giản. <img src="'+R+'" alt=""></p></li></ul><h2 id="_3-bang-so-sanh-tong-ket-nen-tang" tabindex="-1">3. Bảng so sánh tổng kết nền tảng <a class="header-anchor" href="#_3-bang-so-sanh-tong-ket-nen-tang" aria-label="Permalink to “3. Bảng so sánh tổng kết nền tảng”">​</a></h2><table tabindex="0"><thead><tr><th><strong>Nền tảng</strong></th><th><strong>Đánh giá</strong></th><th><strong>Platform</strong></th><th><strong>Ghi chú</strong></th></tr></thead><tbody><tr><td><strong><a href="https://lovable.dev/" target="_blank" rel="noreferrer">Lovable</a></strong></td><td>Rất thân thiện với người mới lập trình AI, dễ bắt đầu, trải nghiệm mượt mà, là lựa chọn khởi đầu lý tưởng.</td><td>Web-based</td><td>Tự động hoàn tất kết nối Supabase, giảm chi phí cấu hình.</td></tr><tr><td><strong><a href="https://cursor.com/cn/agents" target="_blank" rel="noreferrer">Cursor</a></strong></td><td>Phù hợp người dùng đã có kinh nghiệm phát triển, nâng cao năng suất và chất lượng code đáng kể.</td><td>PC</td><td>Cần nền tảng lập trình nhất định, cần tự hiểu cấu trúc dự án và dependency trong môi trường cục bộ.</td></tr><tr><td><strong><a href="https://chat.z.ai/" target="_blank" rel="noreferrer">Z.ai</a></strong></td><td>Phù hợp hơn cho người có nền tảng lập trình, muốn trực tiếp nghiên cứu chi tiết code AI output.</td><td>Web-based</td><td>Không có cửa sổ xem trước, kiểm tra kết quả khá phiền; cần thủ công paste code, tạo thư mục và file và chạy service thủ công.</td></tr><tr><td><strong><a href="https://replit.com/~" target="_blank" rel="noreferrer">Replit</a></strong></td><td>Khuyến nghị cho người muốn nhanh biến ý tưởng thành dịch vụ online có thể truy cập.</td><td>Web-based</td><td>Phát triển và triển khai trực tuyến tất cả trong một, hỗ trợ phối hợp và cung cấp editor trực quan.</td></tr><tr><td><strong><a href="https://agent.minimaxi.com/" target="_blank" rel="noreferrer">Minimax</a></strong></td><td>Phù hợp người muốn xem toàn bộ quá trình AI tự động tìm và sửa lỗi, và học từ đó, nhưng tổng thể khá chậm và tốn Token.</td><td>Web-based</td><td>Toàn bộ quá trình khá dài, AI sẽ nhiều lần tự động chạy test và sửa lỗi.</td></tr><tr><td><strong><a href="https://www.trae.ai/" target="_blank" rel="noreferrer">Trae</a></strong></td><td>Dành cho người có kinh nghiệm lập trình, muốn sử dụng tổ hợp desktop IDE + AI Agent, là công cụ nâng cao hiệu quả mạnh mẽ.</td><td>PC</td><td>Cần cài đặt cục bộ và cấu hình môi trường, nhưng hiệu năng tốt hơn, phù hợp tiến hành dự án Vibe Coding dài hạn.</td></tr><tr><td><strong><a href="https://v0.app/" target="_blank" rel="noreferrer">V0</a></strong></td><td>Tối ưu cho người phi nhà phát triển muốn nhanh tạo hiệu ứng UI React, phù hợp sinh viên hướng frontend / thiết kế.</td><td>Web-based</td><td>Tập trung tạo UI React, cần phối hợp với nền tảng khác hoàn thành backend và xây dựng ứng dụng hoàn chỉnh.</td></tr></tbody></table><hr><h2 id="title-so-sanh-7-cong-cu-lap-trinh-ai-description-danh-gia-thuc-hanh-cac-nen-tang-web-vibe-coding-bang-mot-bai-toan-thong-nhat-so-sanh-do-de-lam-quen-kiem-soat-code-va-trien-khai" tabindex="-1">title: &#39;So sanh 7 cong cu lap trinh AI&#39; description: &#39;Danh gia thuc hanh cac nen tang Web Vibe Coding bang mot bai toan thong nhat, so sanh do de lam quen, kiem soat code va trien khai.&#39; <a class="header-anchor" href="#title-so-sanh-7-cong-cu-lap-trinh-ai-description-danh-gia-thuc-hanh-cac-nen-tang-web-vibe-coding-bang-mot-bai-toan-thong-nhat-so-sanh-do-de-lam-quen-kiem-soat-code-va-trien-khai" aria-label="Permalink to “title: &#39;So sanh 7 cong cu lap trinh AI&#39;description: &#39;Danh gia thuc hanh cac nen tang Web Vibe Coding bang mot bai toan thong nhat, so sanh do de lam quen, kiem soat code va trien khai.&#39;”">​</a></h2>',97)])])}const $=t(U,[["render",K]]);export{F as __pageData,$ as default};
